af)softRaf=requestAnimationFrame(runSoft);};const goTo=index=>{const clamped=Math.max(0,Math.min(panels.length-1,index));const startY=window.scrollY;const end=targetY(panels[clamped]);if(Math.abs(end-startY)<2||animating)return;stopSoft();animating=true;const t0=performance.now();const step=now=>{const t=Math.min(1,(now-t0)/duration);window.scrollTo(0,startY+(end-startY)*ease(t));if(t<1)requestAnimationFrame(step);else animating=false;};requestAnimationFrame(step);};const nestedAllows=(el,delta)=>{const scroller=el?.closest?.(".timeline-scroll");if(!scroller)return false;const top=scroller.scrollTop;const max=scroller.scrollHeight-scroller.clientHeight;if(delta>0&&top<max-1)return true;if(delta<0&&top>1)return true;return false;};const sectionAllows=(el,delta)=>{if(!isPinStart(el))return false;const{pinY,maxY}=pinRange(el);const y=softRaf?softTo:window.scrollY;if(delta>0&&y<maxY-2)return true;if(delta<0&&y>pinY+2)return true;return false;};const onDelta=delta=>{if(!delta||animating)return;const current=nearestIndex();const el=panels[current];if(sectionAllows(el,delta)){freeScroll(el,Math.sign(delta)*Math.min(Math.abs(delta),180));return;}goTo(current+(delta>0?1:-1));};window.addEventListener("wheel",e=>{if(nestedAllows(e.target,e.deltaY))return;e.preventDefault();if(animating)return;const current=nearestIndex();const el=panels[current];if(sectionAllows(el,e.deltaY)){freeScroll(el,e.deltaY);return;}onDelta(e.deltaY);},{passive:false});window.addEventListener("keydown",e=>{if(e.defaultPrevented||e.altKey||e.ctrlKey||e.metaKey)return;const tag=(e.target instanceof Element?e.target.tagName:"");if(tag==="INPUT"||tag==="TEXTAREA"||tag==="SELECT"||(e.target instanceof Element&&e.target.isContentEditable))return;if(["ArrowDown","PageDown"," "].includes(e.key)){e.preventDefault();onDelta(Math.round(window.innerHeight*0.32));}else if(["ArrowUp","PageUp"].includes(e.key)){e.preventDefault();onDelta(-Math.round(window.innerHeight*0.32));}});window.addEventListener("touchstart",