const rerun=document.getElementById("rerun");const status=document.getElementById("action-status");rerun?.addEventListener("click",async()=>{rerun.disabled=true;status.textContent="running the example again…";try{const response=await fetch("/api/rerun",{method:"POST"});if(!response.ok)throw new Error(await response.text());status.textContent="finished; refreshing the page…";window.location.reload()}catch(error){status.textContent="the demo could not run: "+(error instanceof Error?error.message:String(error));rerun.disabled=false}});
(()=>{const panels=[...document.querySelectorAll(".hero,.section")];if(panels.length<2)return;let animating=false;let touchY=null;let softRaf=null;let softFrom=0;let softTo=0;let softT0=0;const duration=1100;const softDur=520;const ease=t=>t<0.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;const softEase=t=>1-Math.pow(1-t,3);const isPinStart=el=>el.classList.contains("pin-start");const topbarH=()=>{const bar=document.querySelector(".topbar");return (bar instanceof HTMLElement?bar.getBoundingClientRect().height:72)+12;};const maxScroll=()=>Math.max(0,document.documentElement.scrollHeight-window.innerHeight);const pinRange=el=>{const head=el.querySelector(".section-head")||el;const pinY=Math.max(0,head.getBoundingClientRect().top+window.scrollY-topbarH());const rect=el.getBoundingClientRect();const bottom=rect.top+window.scrollY+rect.height;const maxY=Math.max(pinY,bottom-window.innerHeight);return{pinY,maxY:Math.min(maxY,maxScroll())};};const targetY=el=>{if(isPinStart(el))return pinRange(el).pinY;const rect=el.getBoundingClientRect();const mid=rect.top+window.scrollY+rect.height/2;return Math.max(0,Math.min(mid-window.innerHeight/2,maxScroll()));};const nearestIndex=()=>{const viewMid=window.scrollY+window.innerHeight/2;let best=0,bestDist=Infinity;panels.forEach((el,i)=>{const rect=el.getBoundingClientRect();const mid=rect.top+window.scrollY+rect.height/2;const dist=Math.abs(mid-viewMid);if(dist<bestDist){bestDist=dist;best=i;}});return best;};const stopSoft=()=>{if(softRaf){cancelAnimationFrame(softRaf);softRaf=null;}};const runSoft=now=>{const t=Math.min(1,(now-softT0)/softDur);window.scrollTo(0,softFrom+(softTo-softFrom)*softEase(t));if(t<1)softRaf=requestAnimationFrame(runSoft);else softRaf=null;};const freeScroll=(el,delta)=>{const{pinY,maxY}=pinRange(el);const base=softRaf?softTo:window.scrollY;const next=Math.max(pinY,Math.min(base+delta*0.72,maxY));if(Math.abs(next-window.scrollY)<0.5&&!softRaf)return;softFrom=window.scrollY;softTo=next;softT0=performance.now();if(!softRaf)softRaf=requestAnimationFrame(runSoft);};const goTo=index=>{const clamped=Math.max(0,Math.min(panels.length-1,index));const startY=window.scrollY;const end=targetY(panels[clamped]);if(Math.abs(end-startY)<2||animating)return;stopSoft();animating=true;const t0=performance.now();const step=now=>{const t=Math.min(1,(now-t0)/duration);window.scrollTo(0,startY+(end-startY)*ease(t));if(t<1)requestAnimationFrame(step);else animating=false;};requestAnimationFrame(step);};const nestedAllows=(el,delta)=>{const scroller=el?.closest?.(".timeline-scroll");if(!scroller)return false;const top=scroller.scrollTop;const max=scroller.scrollHeight-scroller.clientHeight;if(delta>0&&top<max-1)return true;if(delta<0&&top>1)return true;return false;};const sectionAllows=(el,delta)=>{if(!isPinStart(el))return false;const{pinY,maxY}=pinRange(el);const y=softRaf?softTo:window.scrollY;if(delta>0&&y<maxY-2)return true;if(delta<0&&y>pinY+2)return true;return false;};const onDelta=delta=>{if(!delta||animating)return;const current=nearestIndex();const el=panels[current];if(sectionAllows(el,delta)){freeScroll(el,Math.sign(delta)*Math.min(Math.abs(delta),180));return;}goTo(current+(delta>0?1:-1));};window.addEventListener("wheel",e=>{if(nestedAllows(e.target,e.deltaY))return;e.preventDefault();if(animating)return;const current=nearestIndex();const el=panels[current];if(sectionAllows(el,e.deltaY)){freeScroll(el,e.deltaY);return;}onDelta(e.deltaY);},{passive:false});window.addEventListener("keydown",e=>{if(e.defaultPrevented||e.altKey||e.ctrlKey||e.metaKey)return;const tag=(e.target instanceof Element?e.target.tagName:"");if(tag==="INPUT"||tag==="TEXTAREA"||tag==="SELECT"||(e.target instanceof Element&&e.target.isContentEditable))return;if(["ArrowDown","PageDown"," "].includes(e.key)){e.preventDefault();onDelta(Math.round(window.innerHeight*0.32));}else if(["ArrowUp","PageUp"].includes(e.key)){e.preventDefault();onDelta(-Math.round(window.innerHeight*0.32));}});window.addEventListener("touchstart",e=>{touchY=e.changedTouches[0]?.clientY??null},{passive:true});window.addEventListener("touchend",e=>{if(touchY==null||animating)return;const y=e.changedTouches[0]?.clientY??touchY;const delta=touchY-y;touchY=null;if(Math.abs(delta)<48)return;if(nestedAllows(e.target,delta))return;onDelta(delta);},{passive:true});if("scrollRestoration" in history)history.scrollRestoration="manual";window.scrollTo(0,targetY(panels[0]));})();
